import os,json,struct,re
p='store/jobs/j000053/out/file.0xab0b138ce9f0.0xab0b1052da20.SharedCacheMap.app.asar.vacb'
with open(p,'rb') as f:
 h=f.read(16);header_len=struct.unpack('<I',h[12:16])[0];head=json.loads(f.read(header_len));base=8+struct.unpack('<I',h[4:8])[0]
 files=[]
 def walk(t,p=''):
  for n,d in t.get('files',{}).items():
   name=p+n
   if 'files' in d:walk(d,name+'/')
   elif 'offset' in d:files.append((name,int(d['offset']),d['size']))
 walk(head)
 json.dump({'base':base,'files':files},open(os.environ['OUT']+'/asar_inventory.json','w'))
 snippets=[]
 for n,o,s in files:
  if not n.endswith(('.js','.json')):continue
  f.seek(base+o);b=f.read(s)
  for term in [b'getPriceOnClose',b'getHistoricalAssetDailyPriceSelector',b'getHistoricalAssetHourlyPriceSelector']:
   for m in re.finditer(re.escape(term),b):
    snippets.append({'file':n,'file_offset':m.start(),'asar_offset':base+o+m.start(),'term':term.decode(),'context':b[max(0,m.start()-700):m.start()+1500].decode(errors='replace')})
 json.dump(snippets,open(os.environ['OUT']+'/price_code.json','w'),indent=2)
 print('files',len(files),'base',base,'snippets',len(snippets))
